class stringx {
  void* rep;
};

stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class vm_stack {
  int salloc;
  char* buffer;
  char* SP;
  void* my_thread;
public:
  bool push(const char* src, int n);
};

class script_object;
class script_library_class;

class vm_executable {
  script_object* owner;
  stringx name;
  stringx fullname;
  char parameters[12];
  int parms_stacksize;
  bool static_func;
  bool linked;
  unsigned short* buffer;
  int buffer_len;
public:
  const stringx& get_fullname() const { return fullname; }
  int get_parms_stacksize() const { return parms_stacksize; }
  const unsigned short* get_start() const { return buffer; }
};

class vm_thread;

class script_object {
public:
  class instance {
    stringx name;
    char data[12];
    char threads[12];
    bool suspended;
  public:
    const stringx& get_name() const { return name; }
    vm_thread* add_thread(const vm_executable* ex);
    vm_thread* add_thread(const vm_executable* ex, const char* parms);
  };
};

class vm_thread {
  script_object::instance* inst;
  const vm_executable* ex;
  unsigned int flags;
  vm_stack dstack;
  const unsigned short* PC;
public:
  vm_stack& get_data_stack() { return dstack; }
  friend class script_object::instance;
};

vm_thread* script_object::instance::add_thread( const vm_executable* ex, const char* parms )
  {
  vm_thread* nt = add_thread( ex );
  if (nt == 0) __builtin_trap();

  if ( parms && !nt->get_data_stack().push( parms, ex->get_parms_stacksize() ) )
    error( get_name() + ": stack overflow spawning " + ex->get_fullname() );
  nt->PC = ex->get_start();
  return nt;
  }
